   "sintesis": "Jensen Huang admitió haber sido \"infiel\" a su esposa y afirmó que cooperará con la investigación de seguridad. El gigante de la fabricación de chips afirmó que su junta directiva no tenía motivos para creer que los secretos de la empresa o la seguridad nacional de EE.UU. se hubieran visto afectados y añadió que el director ejecutivo estaba comprometido a seguir liderando la compañía.",
